<?php
 namespace QQWorld\Catalog\Ui\Component\Listing\Columns; use QQWorld\Framework\View\Element\UiComponentFactory; use QQWorld\Framework\View\Element\UiComponent\ContextInterface; use QQWorld\Catalog\Model\Product\Attribute\Source\Status; use QQWorld\Catalog\Api\Data\ProductInterface; class StatusText extends \QQWorld\Ui\Component\Listing\Columns\Column { protected $status; public function __construct( ContextInterface $context, UiComponentFactory $uiComponentFactory, Status $status, array $components = [], array $data = [] ) { parent::__construct($context, $uiComponentFactory, $components, $data); $this->status = $status; } public function prepareDataSource(array $dataSource) { $dataSource = parent::prepareDataSource($dataSource); if (empty($dataSource['data']['items'])) { return $dataSource; } $fieldName = $this->getData('name'); $sourceFieldName = ProductInterface::STATUS; foreach ($dataSource['data']['items'] as &$item) { if (!empty($item[$sourceFieldName])) { $item[$fieldName] = $this->status->getOptionText($item[$sourceFieldName]); } } return $dataSource; } } 